right:-.6em
}

.timeline-item--active {
top:50%;
opacity:1
}

.timeline-item--active .timeline__content-title {
margin:-50px 0 20px
}

@media only screen and (max-width: 767px) {
div.prizes {
display:none;
font-size:1em;
font-family:'Pathway Gothic One', sans-serif;
position:absolute;
padding-left:2em;
text-align:left;
top:-1.2em;
width:80%
}

.timeline-item--active div.prizes {
display:block;
left:10px
}

.timeline-item--active div.prizes.fields {
width:1em;
height:1em;
top:.2em;
left:.8em
}

.timeline-item {
padding-bottom:40px
}
}

.timeline__img {
}

.timeline-container {
position:absolute;
left:0;
top:0;
width:100%;
height:100%
}

.timeline-header {
width:100%;
text-align:center;
margin-bottom:80px;
padding-bottom:20px;
position:relative
}

.timeline-header__title {
color:#fff;
font-size:46px;
font-family:Cardo;
font-weight:400;
margin:0
}

.timeline-header__subtitle {
font-family:'Pathway Gothic One', sans-serif;
font-size:1.2em;
letter-spacing:2px;
margin:10px 0 0;
font-weight:400
}

.demo-footer {
padding:60px 0;
text-align:center
}

.demo-footer a {
color:#999;
display:inline-block;
font-family:Cardo
}
